export const MUSIC_MODES = [`off`, `menu`, `endless`, `platform`];

const TAU = Math.PI * 2;
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const mtof = (m) => 440 * Math.pow(2, (m - 69) / 12);
export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ============================================================================ 1. synthesis helpers
const noiseBuffers = new WeakMap();
function noiseBuffer(ctx) {
  let buf = noiseBuffers.get(ctx);
  if (!buf) {
    const n = Math.floor(ctx.sampleRate * 2), r = mulberry32(12345);
    buf = ctx.createBuffer(1, n, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = r() * 2 - 1;
    noiseBuffers.set(ctx, buf);
  }
  return buf;
}
/** amplitude envelope: ~instant attack `a`, exponential decay over `dur` */
function pluck(g, t0, peak, a, dur) {
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.linearRampToValueAtTime(Math.max(0.0002, peak), t0 + a);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + a + Math.max(0.01, dur));
}
/** one oscillator voice. spec: { at, dur, f0, f1, curve, type, peak, a, detune, vib: { rate, depth } } */
function tone(ctx, out, t, P, V, s) {
  const t0 = t + (s.at ?? 0), dur = s.dur ?? 0.2, a = s.a ?? 0.004;
  const o = ctx.createOscillator();
  o.type = s.type ?? `sine`;
  const f0 = (s.f0 ?? 440) * P, f1 = (s.f1 ?? s.f0 ?? 440) * P;
  o.frequency.setValueAtTime(Math.max(20, f0), t0);
  if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t0 + dur * (s.curve ?? 0.6));
  if (s.detune) o.detune.value = s.detune;
  const g = ctx.createGain();
  pluck(g, t0, (s.peak ?? 0.3) * V, a, dur - a);
  o.connect(g), g.connect(out);
  o.start(t0), o.stop(t0 + dur + 0.06);
  if (s.vib) {
    const l = ctx.createOscillator(), lg = ctx.createGain();
    l.frequency.value = s.vib.rate, lg.gain.value = s.vib.depth * P;
    l.connect(lg), lg.connect(o.frequency), l.start(t0), l.stop(t0 + dur + 0.06);
  }
  return o;
}
/** filtered noise burst. spec: { at, dur, peak, a, type, f0, f1, q, curve } */
function noiseHit(ctx, out, t, r, P, V, s) {
  const t0 = t + (s.at ?? 0), dur = s.dur ?? 0.1, a = s.a ?? 0.003;
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer(ctx);
  const f = ctx.createBiquadFilter();
  f.type = s.type ?? `bandpass`;
  const f0 = (s.f0 ?? 1000) * P, f1 = (s.f1 ?? s.f0 ?? 1000) * P;
  f.frequency.setValueAtTime(clamp(f0, 20, 18000), t0);
  if (f1 !== f0) f.frequency.exponentialRampToValueAtTime(clamp(f1, 20, 18000), t0 + dur * (s.curve ?? 0.7));
  f.Q.value = s.q ?? 1;
  const g = ctx.createGain();
  pluck(g, t0, (s.peak ?? 0.3) * V, a, dur - a);
  src.connect(f), f.connect(g), g.connect(out);
  src.start(t0, r() * 1.6), src.stop(t0 + dur + 0.06);
}
function makeVoice(ctx, out, t, r, o = {}) {
  const P = o.pitch ?? 1, V = o.vol ?? 1;
  return { ctx, out, t, r, P, V, tone: (s) => tone(ctx, out, t, P, V, s), noise: (s) => noiseHit(ctx, out, t, r, P, V, s), jit: (k = 0.1) => 1 + (r() * 2 - 1) * k };
}

// ============================================================================ 2. SFX recipes (each returns its length in seconds)
const NOTE = { C5: 523.25, D5: 587.33, E5: 659.25, G5: 783.99, A5: 880, B5: 987.77, C6: 1046.5, E6: 1318.5, G6: 1568, C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392, B4: 493.88 };
/** marimba-like plink used by jingles and the music */
function plink(c, at, f, dur = 0.3, peak = 0.3) {
  c.tone({ at, dur, f0: f, peak, a: 0.003 });
  c.tone({ at, dur: dur * 0.35, f0: f * 3.98, peak: peak * 0.3, a: 0.002 });
}
