// ============================================================================ 3. music composer (pure: no audio objects, seeded, headless testable)
export const SCALES = { lydian: [0, 2, 4, 6, 7, 9, 11], dorian: [0, 2, 3, 5, 7, 9, 10], mixolydian: [0, 2, 4, 5, 7, 9, 10] };
