const RHYTHMS = [[0, 3, 6, 8, 11, 14], [0, 2, 4, 8, 10, 12], [0, 4, 6, 8, 12], [0, 3, 4, 7, 8, 12, 14], [0, 6, 8, 14], [0, 2, 6, 8, 10, 14]];
