// ============================================================================ 5. engine
const MIN_GAP = { step: 0.1, stepAlien: 0.09, impact: 0.06, impactHard: 0.12, splat: 0.05, splatHit: 0.05, tentacle: 0.2, squish: 0.15, hurtAlien: 0.1, hurtPlayer: 0.2, combo: 0.06, coin: 0.04 };
const HIGH_PRIORITY = new Set([`ko`, `playerDie`, `hurtPlayer`, `gameOver`, `newBest`, `levelUp`, `waveClear`, `uiClick`, `uiBack`, `pause`, `resume`, `boulderHit`, `impactHard`]);

